package org.apache.commons.math.analysis.solvers;

import java.io.*;
import java.math.*;
import java.util.*;
import org.apache.commons.math.analysis.UnivariateRealFunction;
import org.apache.commons.math.exception.ConvergenceException;
import org.apache.commons.math.exception.MathInternalError;
import org.apache.commons.math.util.FastMath;
import org.apache.commons.math3.analysis.UnivariateRealFunction;
import org.apache.commons.math3.exception.MathInternalError;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.fail;

/**
 * Unit tests for BaseSecantSolver.doSolve().
 * Since doSolve() is protected, we use a Testable subclass to expose it and control dependencies.
 */
public class BaseSecantSolver_doSolve_TriageGen0Test {

    // Mocking the internal state and dependencies via a Testable subclass
    private static class TestableSecantSolver extends BaseSecantSolver {
        private UnivariateRealFunction function;
        private double min;
        private double max;
        private double ftol = 1e-10;
        private double atol = 1e-10;
        private double rtol = 1e-10;
        private boolean bracketingError = false;

        protected TestableSecantSolver(double rtol, double atol, double ftol, Method method) {
            super(rtol, atol, ftol, method);
            this.ftol = ftol;
            this.atol = atol;
            this.rtol = rtol;
        }

        @Override
        protected double getMin() { return min; }

        @Override
        protected double getMax() { return max; }

        @Override
        protected double computeObjectiveValue(double x) {
            return function.value(x);
        }

        @Override
        protected double getFunctionValueAccuracy() { return ftol; }

        @Override
        protected double getAbsoluteAccuracy() { return atol; }

        @Override
        protected double getRelativeAccuracy() { return rtol; }

        @Override
        protected void verifyBracketing(double x0, double x1) {
            if (bracketingError) {
                throw new IllegalArgumentException("Bracketing error");
            }
        }

        // Helper to set up the test state
        void setup(UnivariateRealFunction f, double min, double max) {
            this.function = f;
            this.min = min;
            this.max = max;
        }

        double callDoSolve() {
            return doSolve();
        }
    }

    @Test
    public void testExactRootAtMin() {
        TestableSecantSolver solver = new TestableSecantSolver(1e-8, 1e-8, 1e-8, BaseSecantSolver.Method.ILLINOIS);
        solver.setup(x -> x - 2.0, 2.0, 5.0);
        assertEquals(2.0, solver.callDoSolve(), 1e-12);
    }

    @Test
    public void testExactRootAtMax() {
        TestableSecantSolver solver = new TestableSecantSolver(1e-8, 1e-8, 1e-8, BaseSecantSolver.Method.ILLINOIS);
        solver.setup(x -> x - 5.0, 0.0, 5.0);
        assertEquals(5.0, solver.callDoSolve(), 1e-12);
    }

    @Test
    public void testExactRootDuringIteration() {
        TestableSecantSolver solver = new TestableSecantSolver(1e-8, 1e-8, 1e-8, BaseSecantSolver.Method.ILLINOIS);
        // Linear function where the secant will hit the root exactly
        solver.setup(x -> x - 1.0, 0.0, 2.0);
        assertEquals(1.0, solver.callDoSolve(), 1e-12);
    }

    @Test
    public void testIllinoisMethod() {
        TestableSecantSolver solver = new TestableSecantSolver(1e-8, 1e-8, 1e-8, BaseSecantSolver.Method.ILLINOIS);
        solver.setup(x -> Math.pow(x, 3) - x, 0.5, 2.0);
        // Root is 1.0
        assertEquals(1.0, solver.callDoSolve(), 1e-7);
    }

    @Test
    public void testPegasusMethod() {
        TestableSecantSolver solver = new TestableSecantSolver(1e-8, 1e-8, 1e-8, BaseSecantSolver.Method.PEGASUS);
        solver.setup(x -> Math.pow(x, 3) - x, 0.5, 2.0);
        assertEquals(1.0, solver.callDoSolve(), 1e-7);
    }

    @Test
    public void testInversionAndAllowedAnySide() {
        TestableSecantSolver solver = new TestableSecantSolver(1e-8, 1e-8, 1e-8, BaseSecantSolver.Method.ILLINOIS);
        // Force an inversion via a non-monotonic function or specific setup
        // Here we simulate the logic by providing a function where the root is found 
        // but the interval flips.
        solver.setup(x -> (x < 1.0) ? (x - 1.0) : (1.0 - x), 0.0, 2.0);
        // The logic depends on AllowedSolution enum which is not visible in snippet but assumed.
        // Since we cannot change 'allowed' in the snippet easily without reflection or changing the class,
        // we assume the default behavior of the solver.
    }

    @Test
    public void testFtolTermination_AnySide() {
        // Set ftol very high so it terminates immediately
        TestableSecantSolver solver = new TestableSecantSolver(1e-8, 1e-8, 10.0, BaseSecantSolver.Method.ILLINOIS);
        solver.setup(x -> x - 1.0, 0.0, 2.0);
        // It will compute x = 2 - ( (1 * 2) / (1 - (-1)) ) = 1.0. 
        // fx will be 0.0. 0.0 <= 10.0.
        assertEquals(1.0, solver.callDoSolve(), 1e-12);
    }

    @Test
    public void testAccuracyTermination_AnySide() {
        // Set atol/rtol very high
        TestableSecantSolver solver = new TestableSecantSolver(1e-8, 10.0, 1e-8, BaseSecantSolver.Method.ILLINOIS);
        solver.setup(x -> x - 1.0, 0.0, 2.0);
        // x0=0, x1=2, f0=-1, f1=1. Next x=1, fx=0.
        // If fx=0, it returns immediately.
        // To test the interval check, we need fx != 0.
        solver.setup(x -> x - 1.00000000001, 0.0, 2.0);
        double result = solver.callDoSolve();
        assertEquals(1.00000000001, result, 1e-5);
    }

    @Test(expected = MathInternalError.class)
    public void testInvalidMethodThrowsError() {
        // Using a method that isn't handled (hypothetically if method enum had more values)
        // Since we can't easily inject a new enum value, we assume the 'default' case in switch
        // is reached if the method is somehow corrupted.
        // This is hard to trigger without reflection on the 'method' field.
    }

    @Test
    public void testRegulaFalsiMethod() {
        // REGULA_FALSI has an empty switch block in the provided code
        TestableSecantSolver solver = new TestableSecantSolver(1e-8, 1e-8, 1e-8, BaseSecantSolver.Method.REGULA_FALSI);
        solver.setup(x -> x - 1.0, 0.0, 2.0);
        assertEquals(1.0, solver.callDoSolve(), 1e-7);
    }
}
